/*
 * NeuTTS Air — open, on-device text-to-speech with instant voice cloning (Neuphonic, Apache 2.0).
 *
 * The model is a Qwen 0.5B backbone with a NeuCodec audio codec. It runs on CPU via llama-cpp-python
 * (GGUF) or onnxruntime; the browser cannot run it natively, so the voice references are
 * pre-generated by `scripts/build-neutts-voices.ts` and shipped as a small JSON file
 * (`static/voices/neutts-voices.json`). At runtime the browser only decodes the codec — the
 * heavy inference happens in the pre-built script.
 *
 * The reference JSON is keyed by character id and contains the encoded voice codes plus the
 * description and reference text that produced them. The story cast picks the right entry by id.
 */
import neuttsVoices from '#lib/data/neutts-voices.json';

export type NeuttsVoice = { description: string; text: string; codes: number[] };

export function neuttsVoicesFor() {
  return neuttsVoices as Record<string, NeuttsVoice>;
}

export function neuttsVoiceFor(character: string): NeuttsVoice | null {
  return (neuttsVoices as Record<string, NeuttsVoice>)[character] ?? null;
}